type ProvenanceOverrides = {
  sourceUrl?: string;
  sourceOrganization?: string;
  verificationStatus?: NonNullable<Waterbody["verificationStatus"]>;
  accessType?: NonNullable<Waterbody["accessType"]>;
  activities?: Waterbody["activities"];
};

function fl(
  id: string,
  name: string,
  region: string,
  county: string,
  waterType: Waterbody["waterType"],
  latitude: number,
  longitude: number,
  speciesIds: string[],
  status: Waterbody["status"],
  shoreAccessDifficulty: NonNullable<Waterbody["shoreAccessDifficulty"]>,
  beginnerDifficulty: Waterbody["beginnerDifficulty"],
  parkingNote: string,
  regulationSummary: string,
  suggestedBait: string[],
  recommendedRigs: string[],
  bestSeason: string,
  todayRecommendation: string,
  provenance: ProvenanceOverrides = {}
): Waterbody {
  return {
    id,
    waterbodyId: `FWC-FL-${id.toUpperCase().replaceAll("-", "_")}`,
    name,
    regionId: "florida",
    region,
    county,
    city: region,
    source: "FWC fishing regulations; FWC freshwater and saltwater resources",
    lastUpdated: "May 2026",
    regulationReference: "Verify in the current FWC freshwater/saltwater regulations summary before fishing.",
    boatLaunchReference: "Verify launch status in FWC boat ramp listings.",
    waterType,
    latitude,
    longitude,
    speciesIds,
    shoreAccessDifficulty,
    parkingNote,
    bestSeason,
    officialLink: fishFlorida,
    boatLaunch: waterType === "Lake" || waterType === "Saltwater" || waterType === "River",
    kayakFriendly: waterType !== "Pier" && beginnerDifficulty !== "Advanced",
    bankFishing: waterType !== "Saltwater" || beginnerDifficulty !== "Advanced",
    wheelchairAccessible: beginnerDifficulty === "Easy" && (waterType === "Pier" || waterType === "Lake"),
    bathrooms: beginnerDifficulty === "Easy" || waterType === "Pier",
    camping: ["lake-kissimmee", "rodman-reservoir", "lake-talquin", "bahia-honda-bridge"].includes(id),
    fee: ["bahia-honda-bridge", "sebastian-inlet-pier"].includes(id) ? "Parking or day-use fee may apply" : "Usually free or varies by access point",
    photoPlaceholder: `${name} photo placeholder`,
    familyFriendly: beginnerDifficulty === "Easy" && shoreAccessDifficulty === "Easy",
    status,
    regulationSummary: `Mock guidance: ${regulationSummary}`,
    suggestedBait,
    recommendedRigs,
    beginnerSetup: `${recommendedRigs[0]} with ${suggestedBait[0]}; verify official rules first.`,
    beginnerDifficulty,
    notes: `${parkingNote} ${regulationSummary}`,
    todayRecommendation,
    youtubeSearch: `${name} fishing beginner ${recommendedRigs[0]}`,
    activities: provenance.activities ?? ["fishing"],
    sourceUrl: provenance.sourceUrl,
    sourceOrganization: provenance.sourceOrganization,
    verificationStatus: provenance.verificationStatus,
    accessType: provenance.accessType
  };
}
